package shape

import (
	"context"
	"fmt"
	"regexp"
	"strings"
	"sync"
	"testing"

	"github.com/KogenAI/kogen-executor/executor"
)

// TestExternalChecksPrintProgress uses the same model-free executor as the
// decision/literal tests. Both checks finish twice, including a refused draft.
func TestExternalChecksPrintProgress(t *testing.T) {
	f := newShpFx(t)
	f.useExternalShape()
	var mu sync.Mutex
	var output strings.Builder
	// Only the captured progress writer is shared by the concurrent checks.
	writer := &externalCheckProgressWriter{mu: &mu, output: &output}
	text := func() string { mu.Lock(); defer mu.Unlock(); return output.String() }
	calls := map[string]int{}
	var callsMu sync.Mutex
	check := func(kind string) func(int, string) (executor.RoundResult, error) {
		return func(n int, root string) (executor.RoundResult, error) {
			callsMu.Lock()
			calls[kind]++
			i := calls[kind]
			callsMu.Unlock()
			start := "kogen: checking the stated decisions"
			if kind == "literal" {
				start = "kogen: checking the required literals"
			}
			before := text()
			if strings.Count(before, start) != i || strings.Count(before, "kogen: "+kind+" check finished") != i-1 {
				t.Errorf("%s round %d did not announce exactly one start before execution: %s", kind, i, before)
			}
			payload := map[string]any{"items": []any{}}
			if kind == "literal" {
				status := "required"
				if i > 1 {
					status = "informal"
				}
				payload["items"] = []any{map[string]any{"literal": "ZeroDivisionError", "source": "request", "source_quote": "Raise exactly ZeroDivisionError for 0.", "status": status, "package_value": "", "why": "because"}}
			}
			return result(payload)(n, root)
		}
	}
	ack := map[string]any{"files": []any{map[string]any{"path": ".kogen/intents/is-even/acceptance.feature", "content": shpFeature}}}
	x := &shapeExec{t: t, rounds: []func(int, string) (executor.RoundResult, error){result(shpFiles()), result(shpFiles()), result(ack)}, decision: []func(int, string) (executor.RoundResult, error){check("decision")}, literal: []func(int, string) (executor.RoundResult, error){check("literal")}}
	f.newSession()
	f.S.Stderr = writer
	exit, err := Shape(context.Background(), f.S, ShapeInput{Project: f.Root, Tools: fixtureTools(f.S), Slug: shpSlug, Request: "Add calc.is_even(n). Raise exactly ZeroDivisionError for 0.", Client: f.Client, External: x.external()})
	if err != nil || exit != 0 {
		t.Fatalf("Shape exit=%d err=%v\n%s", exit, err, text())
	}
	for _, kind := range []string{"decision", "literal"} {
		var lines []string
		for _, line := range strings.Split(text(), "\n") {
			if strings.Contains(line, "kogen: "+kind+" check finished") || (kind == "decision" && strings.Contains(line, "kogen: checking the stated decisions")) || (kind == "literal" && strings.Contains(line, "kogen: checking the required literals")) {
				lines = append(lines, line)
			}
		}
		if len(lines) != 4 {
			t.Errorf("%s: want two start/finish pairs, got %q", kind, lines)
			continue
		}
		for i := 0; i < 2; i++ {
			if !regexp.MustCompile(fmt.Sprintf(`^kogen: %s check finished \([0-9]+ s\)$`, kind)).MatchString(lines[2*i+1]) {
				t.Errorf("%s finish format/order: %q", kind, lines)
			}
		}
	}
	noNativeRequests(t, f)
}

type externalCheckProgressWriter struct {
	mu     *sync.Mutex
	output *strings.Builder
}

func (w *externalCheckProgressWriter) Write(p []byte) (int, error) {
	w.mu.Lock()
	defer w.mu.Unlock()
	return w.output.Write(p)
}
